const dangerText=a=>`${a.danger} · ${a.hitsToWin} coup${a.hitsToWin>1?'s':''} pour vaincre, ${a.hitsAbsorbed} encaissable${a.hitsAbsorbed>1?'s':''}`;
function render(){for(const [id,val] of Object.entries({gold:Math.floor(s.gold).toLocaleString('fr-FR'),stage:String(s.stage).padStart(2,'0'),floor:`Étage ${s.stage}${f.boss?' · Gardien':''}`,level:s.level,attack:attack(),health:`${Math.max(0,Math.ceil(f.hp))} / ${maxHP()}`,reward:reward(),xptext:`${s.xp} / ${xpNeeded(s)}`,progress:`${s.kills} / ${KILLS_PER_STAGE} ennemis vaincus`,enemy:f.boss?'Le Gardien de braise':names[(s.stage-1)%3],enemyhp:`${Math.max(0,Math.ceil(f.enemyHP))} / ${f.enemyMax}`}))$(id).textContent=val;{const a=assess(s,f);$('danger').textContent=`Puissance ${a.attack} par coup · ${dangerText(a)}`;$('danger').className='danger d-'+a.danger.toLowerCase().replace('û','u').replace('é','e')}$('xpbar').style.width=`${s.xp/xpNeeded(s)*100}%`;$('enemybar').style.width=`${f.enemyHP/f.enemyMax*100}%`;$('dots').innerHTML=Array.from({length:KILLS_PER_STAGE},(_,i)=>`<i class="${i<s.kills?'done':''}"></i>`).join('');$('boss').disabled=s.kills<KILLS_PER_STAGE||f.boss;$('boss').innerHTML=f.boss?'⚔ Gardien en cours…':`⚔ Affronter le gardien<small>${s.kills>=KILLS_PER_STAGE?'Prêt · ouvre le prochain étage':`${KILLS_PER_STAGE} victoires requises`}</small>${f.boss?'':`<small>Gardien : ${dangerText(assessGuardian(s))}</small>`}`;$('power').disabled=cool>0||paused;$('cooldown').textContent=cool>0?`Recharge · ${cool} s`:`Dégâts × ${SKILL_MULT} · prêt`;for(const k of ['weapon','armor','luck']){const b=$('buy-'+k);b.disabled=s.gold<cost(k);b.textContent=`◈ ${cost(k)}`;$('desc-'+k).textContent=`Niv. ${s[k]} · ${k==='weapon'?`+${ATTACK_PER_WEAPON} attaque`:k==='armor'?`+${HEALTH_PER_ARMOR} vitalité`:`+${REWARD_PER_LUCK} or / victoire`}`}}
for(const [k,title,img] of [['weapon','Affûter la lame',104],['armor','Renforcer l’armure',100],['luck','Charme de fortune',110]]){const row=document.createElement('div');row.className='upgrade';row.innerHTML=`<img src="assets/Tiles/tile_${String(img).padStart(4,'0')}.png" alt=""><div><b>${title}</b><p id="desc-${k}"></p></div><button id="buy-${k}" aria-label="${title}"></button>`;$('upgrades').append(row);$('buy-'+k).onclick=()=>{if(s.gold<cost(k))return;run(buyUpgrade(s,f,k));save();render()}}
function strike(mult=1){if(paused)return;run(strikeOf(s,f,mult));render()}
$('boss').onclick=()=>{run(startBoss(s,f));render()};$('power').onclick=()=>{if(cool||paused)return;cool=SKILL_COOLDOWN_SECONDS;strike(SKILL_MULT)};$('pause').onclick=()=>{paused=!paused;emit('braise:pause',paused);$('pause').textContent=paused?'▶ Reprendre':'Ⅱ Pause';render()};$('reset').onclick=()=>{if(!confirm('Recommencer ? Toute la progression locale sera effacée.'))return;s=fresh();cool=0;hideBossPanel();run(newFight(s));save();render();log('Une nouvelle braise s’éveille.')};$('export').onclick=()=>{const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([serializeSave(s,{hp:f.hp,boss:f.boss,enemyHP:f.enemyHP,cool})],{type:'application/json'}));a.download='braise-sauvegarde.json';a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000);log('Sauvegarde exportée.')};$('import').onclick=()=>$('importfile').click();$('importfile').onchange=async e=>{const file=e.target.files[0];e.target.value='';if(!file)return;let r={ok:false};try{r=importSave(await file.text(),Date.now())}catch{}if(!r.ok){log('Import refusé : fichier invalide, la partie en cours est inchangée.');return}if(!confirm('Importer cette sauvegarde ? La partie en cours sera remplacée.')){log('Import annulé.');return}s=r.s;cool=r.fight?.cool||0;hideBossPanel();f=restoreFight(s,r.fight);apply({type:'spawn',boss:f.boss});save();render();log('Sauvegarde importée.')};$('claim').onclick=()=>$('welcome').close();$('bossclose').onclick=hideBossPanel;document.addEventListener('keydown',ev=>{if(ev.key==='Escape'&&!$('bosspanel').hidden&&!$('welcome').open)hideBossPanel()});
function collectAway(){const r=offlineGains(s,Date.now(),f,{paused});s=r.s;f=r.f;r.events.forEach(apply);if(r.show){$('offline').textContent=`Pendant ton absence : ${r.wins} ennemis vaincus et ${r.gold.toLocaleString('fr-FR')} pièces d’or récoltées (${OFFLINE_CAP_SECONDS/3600} h maximum).`;if(!$('welcome').open)$('welcome').showModal()}}
collectAway();
apply({type:'spawn',boss:f.boss});render();if(loadStatus==='reset'||loadStatus==='unavailable')log('Sauvegarde illisible ou indisponible : une nouvelle partie commence.');else if(loadStatus==='repaired')log('Sauvegarde endommagée : les valeurs invalides ont été remplacées.');if(loadStatus==='unavailable'){saveOk=false;$('saved').textContent='Sauvegarde indisponible'}setInterval(()=>{if(!document.hidden)strike()},ATTACK_INTERVAL_MS);setInterval(()=>{if(cool>0&&!paused)cool--;if(bossPanelLeft>0&&!paused&&!document.hidden&&--bossPanelLeft===0)hideBossPanel();render()},1000);setInterval(()=>{if(!document.hidden)save()},5000);document.addEventListener('visibilitychange',()=>{if(document.hidden)save();else{collectAway();render()}});window.addEventListener('pagehide',save);
